static int z_t128_sort_lt(z_t53_t _a, z_t53_t _b) { return z_t53_cmp(&_a, &_b) < 0; }
static void z_t128_sort_merge(z_t53_t* data, z_t53_t* scratch, uint64_t lo, uint64_t mid, uint64_t hi) {
    uint64_t i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (!z_t128_sort_lt(data[j], data[i])) scratch[k++] = data[i++];
        else scratch[k++] = data[j++];
    }
    while (i < mid) scratch[k++] = data[i++];
    while (j < hi) scratch[k++] = data[j++];
    memcpy(&data[lo], &scratch[lo], (hi - lo) * sizeof(*data));
}
static void z_t128_sort_rec(z_t53_t* data, z_t53_t* scratch, uint64_t lo, uint64_t hi) {
    if (hi - lo <= 1) return;
    uint64_t mid = lo + (hi - lo) / 2;
    z_t128_sort_rec(data, scratch, lo, mid);
    z_t128_sort_rec(data, scratch, mid, hi);
    z_t128_sort_merge(data, scratch, lo, mid, hi);
}
static void z_t128_sort(z_t128_t* _this) {
    if (_this->length < 2) return;
    z_t53_t* scratch = (z_t53_t*)z_xmalloc(_this->length * sizeof(z_t53_t));
    z_t128_sort_rec(_this->data, scratch, 0, _this->length);
    free(scratch);
}

